const v = $('Parse Application JSON').first().json;
const skills = Array.isArray(v.skills) ? v.skills : [];
const tools = Array.isArray(v.tools) ? v.tools : [];
const yrs = (typeof v.experience_years === 'number' && !isNaN(v.experience_years)) ? v.experience_years : null;
const support = !!v.support_experience;
const eng = (v.english_level || 'none').toString().toLowerCase();
const breakdown = { experience: 0, support: 0, english: 0, tools: 0 };
if (yrs !== null) {
  if (yrs >= 2) breakdown.experience = 40;
  else if (yrs >= 1) breakdown.experience = 25;
  else if (yrs > 0) breakdown.experience = 10;
}
if (support) breakdown.support = 25;
if (eng === 'fluent') breakdown.english = 20;
else if (eng === 'good') breakdown.english = 15;
else if (eng === 'basic') breakdown.english = 5;
if (tools.length > 0) breakdown.tools = 15;
let score = breakdown.experience + breakdown.support + breakdown.english + breakdown.tools;
if (score > 100) score = 100;
const hasInfo = yrs !== null || skills.length > 0 || eng !== 'none' || tools.length > 0;
let status = 'reject';
if (!hasInfo) status = 'more_info';
else if (score >= 70) status = 'shortlist';
else if (score >= 40) status = 'more_info';
return [{ json: { name: v.name, message: v.message, role: 'Customer Support Agent', skills, experience_years: yrs, support_experience: support, english_level: eng, tools, availability: v.availability || '', notes: v.notes || '', score, breakdown, status } }];
